legacy-transition.source:
import {definePrototype} from '@proto.ui/core';
import {asTransition} from '@proto.ui/prototypes-base/transition';
export default definePrototype({name:'legacy-transition-consumer',setup(def){
 const motion=asTransition();def.expose.method('open',()=>motion.controls.enter());
 return r=>r.el('div','Legacy transition');
}});

